	record_count bigint    -- in case of messages that specify what table has been updated: the amount of records updated
)
;

CREATE TABLE etl.etl_run_params
(
	etl_id bigint NOT NULL,    -- id of the etl run
	sequence bigint NOT NULL   DEFAULT NEXTVAL(('etl_seq'::text)::regclass),
