	value_bool boolean    -- char value of the parameter if value_type = bool
)
;

CREATE TABLE etl.validation_results
(
	etl_id bigint NOT NULL,    -- id of the etl run
	sequence bigint NOT NULL   DEFAULT NEXTVAL(('etl_seq'::text)::regclass),
	identificatie char(100),    -- identification of the object to which the validation pertains. can be null if the validation message is regarding a generic error like schema / file errors 
	begin_geldigheid timestamp,    -- begin_geldigheid of the object to which the validation pertains. can be null if the validation message is regarding a generic error like schema / file errors 
	layer char(100),    -- map layer to which the validation pertains. can be null if the validation message is regarding a generic error like schema / file errors 
	validation_rule char(100) NOT NULL,    -- name of the validation rule. This should be a name from a list of rules according to the GLP
	error_code char(20) NOT NULL,    -- error code  of the validation. This should be a code from a list of rules according to the GLP
	error_type char(10) NOT NULL,    -- level of the error code: values can be  	- info 	- warning 	- error
	error_message text,    -- the error message with its detail description
	corrected boolean NOT NULL,    -- indicates if the validation fault was corrected automatically
	geom geometry    -- geometry of the object to which the validation pertains. can be null if the validation message is regarding a generic error like schema / file errors 
)
;

